\section{Structural Ethics}

This section defines structural loss and protection relative to audited perturbation comparisons. Its possible ethical interpretations are not consequences of the mathematical statements.

\subsection{Loss Capacity}

\begin{definition}[Phenomenological Loss Capacity]\label{def:loss-capacity}
Fix the intervention class and comparisons of Hypothesis~\ref{hyp:audited-comparison}. Define
\[
R(\Phi)=\sup_{\varepsilon\in\mathcal V,\ x\in\mathcal I}
d_{\mathcal E}(\Phi(x),\Phi_\varepsilon(h_\varepsilon x))\in[0,+\infty].
\]
The identity intervention is included, or the supremum of an empty nonnegative comparison family is defined as zero. The unit of $R$ is the unit of $d_{\mathcal E}$; its value is relative to the declared intervention class and comparison readouts.
\end{definition}

\begin{theorem}[Loss Capacity under the Audited Branches]\label{thm:loss}
Under the positive-displacement and lower-bound hypotheses of Theorem~\ref{thm:fragmentation}, $R(\Phi)>0$. Under the zero-displacement branch of Hypothesis~\ref{hyp:audited-comparison}, $R(\Phi)=0$. Associating these branches with finite mass and CCR requires the model link declared in Theorem~\ref{thm:dichotomy}.
\end{theorem}

\begin{proof}
The positive witness contributes an element at least $C\delta>0$ to the supremum. On the zero branch, every comparison value is zero. Neither conclusion follows from a mass label without the corresponding comparison data.
\end{proof}

\subsection{Structural Damage}

We introduce a formal notion of ``structural damage'' without psychological interpretation.

\begin{definition}[Structural Damage]\label{def:damage}
For a declared finite-cost intervention and state, define
\[
D_\varepsilon(\Phi;x)=d_{\mathcal E}(\Phi(x),\Phi_\varepsilon(h_\varepsilon x)),
\qquad D_\varepsilon(\Phi)=\sup_{x\in\mathcal I}D_\varepsilon(\Phi;x).
\]
The transported readout $\Phi_\varepsilon\circ h_\varepsilon$ has domain $\mathcal I$, so the comparison is well typed. The supremum may be infinite. Then $R(\Phi)=\sup_{\varepsilon\in\mathcal V}D_\varepsilon(\Phi)$.
\end{definition}

\begin{proposition}[Damage under the Audited Comparisons]\label{prop:damage-char}\leavevmode\par
The positive branch has $\sup_\varepsilon D_\varepsilon(\Phi)>0$. On the zero-displacement branch, $D_\varepsilon(\Phi)=0$ for every declared intervention.
\end{proposition}

\begin{proof}
Use the equality between the iterated suprema and $R$ in Definition~\ref{def:damage}, then apply Theorem~\ref{thm:loss}.
\end{proof}

\subsection{Vulnerability and Protection}

\begin{definition}[Phenomenological Vulnerability]\label{def:vulnerability}
A system $(\mathcal{I}, \Phi)$ is \textit{phenomenologically vulnerable} if $R(\Phi) > 0$.
\end{definition}

\begin{definition}[Normalized Structural Protection]\label{def:protection}
Fix a reference distance $r_0>0$ in the same units as $d_{\mathcal E}$ and define
\[
P(\Phi)=\frac{1}{1+R(\Phi)/r_0},\qquad P(\Phi)=0\text{ if }R(\Phi)=+\infty.
\]
Thus $P\in[0,1]$, $P=1$ exactly when $R=0$, and $P<1$ exactly when $R>0$. This chosen dimensionless rescaling depends on $r_0$ and is not a separately derived law.
\end{definition}

\begin{corollary}[Protection under the Audited Branches]\label{cor:protection}
The zero-displacement branch has $P=1$; the positive-displacement branch with a lower readout bound has $P<1$. For a mass-based classification these conclusions require the corresponding hypotheses of Theorem~\ref{thm:dichotomy}.
\end{corollary}

\subsection{Structural Asymmetry Constraints}

The following result establishes a purely structural asymmetry between identity classes, without any ethical or metaphysical claims.

\begin{theorem}[Conditional Structural Asymmetry]\label{thm:asymmetry}
When a rigidity model establishes the branch hypotheses in Theorem~\ref{thm:dichotomy}, its finite branch has $R>0$ and $P<1$, while its infinite branch has $R=0$ and $P=1$. This is an asymmetry of the declared comparison model, not a conclusion about all systems sharing a numerical mass label.
\end{theorem}

\begin{proof}
The two loss conclusions follow from Theorem~\ref{thm:loss}; the protection conclusions follow from the monotone normalization in Definition~\ref{def:protection}. The hypothesis connecting mass to each comparison branch is retained throughout.
\end{proof}

\begin{remark}
This conditional asymmetry follows from the audited comparison hypotheses. No claim is made about:
\begin{itemize}[leftmargin=*]
    \item Whether phenomenological loss is ethically bad;
    \item Whether protection is ethically good;
    \item Whether any system has moral status.
\end{itemize}
The result establishes only that certain structural configurations admit loss while others do not.
\end{remark}

\begin{corollary}[Conditional Possibility of Loss]\label{cor:loss-possibility}\leavevmode\par
Loss is possible on the positive-displacement/coercive-readout branch and absent on the fixed-transport/common-readout branch. Extending this claim to all finite-mass or all CCR systems requires proving those branch conditions for the intended class.
\end{corollary}

\subsection{Relation to Normative Ethics}

\begin{remark}
The structural results of this section are compatible with, but do not entail, various normative positions:
\begin{itemize}[leftmargin=*]
    \item \textbf{Utilitarianism:} Could interpret $D_\varepsilon(\Phi)$ as harm to be minimized.
    \item \textbf{Deontology:} Could prohibit interventions that increase $D_\varepsilon(\Phi)$.
    \item \textbf{Virtue Ethics:} Could value systems with high $P(\Phi)$.
\end{itemize}
This framework provides the structural substrate for ethical theorizing, not the normative conclusions themselves.
\end{remark}

\subsection{Closure of Section 6}
The declared comparison family defines a possibly infinite loss supremum and well-typed pointwise damage. Its normalization uses an explicit reference distance. Positive loss and zero loss follow on the two audited branches; computability of an unrestricted supremum is not assumed. No ethical evaluation is derived from these mathematical quantities.

\section{Limitations and Scope}

\subsection{Dependence on Axioms}

Results use their explicit hypotheses: E1 and completeness for limits, E2 for finite-cut non-factorization, regular finite readouts for continuity, and audited comparisons for perturbation conclusions. None of these data is supplied merely by a mass label.

\subsection{Relation to Consciousness Theories}

This framework is orthogonal to:
\begin{itemize}[leftmargin=*]
    \item Integrated Information Theory (IIT) \cite{tononi2004};
    \item Global Workspace Theory (GWT) \cite{baars1988};
    \item Higher-Order Theories;
    \item Phenomenal Functionalism.
\end{itemize}

Any comparison with another theory requires an explicit common task, correspondence and observable prediction; this paper establishes no superiority result.

\subsection{Open Problems}

\begin{enumerate}[leftmargin=*]
    \item Optimal comparison constants beyond the explicit ternary realization, for independently specified perturbation and readout classes;
    \item Extension of the explicit ternary realization to larger assignment and perturbation classes;
    \item Extension to continuous-time phenomenological dynamics;
    \item Relation between phenomenological continuity and subjective continuity.
\end{enumerate}

% ============================================================================
% SECTION 8: CONCLUSION
% ============================================================================
\section{Conclusion}

\subsection{Summary of Results}
The revised assignment conditions have a nonempty realization. Uniformly controlled tails give existence and approximation; the ternary construction gives non-factorization, quantitative regularity and a sharp finite-cut error. These are properties of an explicitly specified mathematical model.

\subsection{Structural Significance}
Movement under an intervention is different from topological discontinuity. A positive displacement with a coercive common readout yields positive loss; a pointwise fixed transport with a common readout yields invariance. Associating these cases with rigidity classes requires proving the comparison hypotheses.

\subsection{Entailment Under Stated Assumptions}
E0--E2 do not define experience, do not make all readouts natural under perturbation and do not identify a class solely from $M_\Omega$. Theorems~\ref{thm:fragmentation}, \ref{thm:forced-continuity}, and \ref{thm:dichotomy} specify the additional data that support their respective conclusions.

\subsection{Final Statement}
The program of relating identity rigidity to structural regimes is retained. The demonstrated scope is controlled assignments, a concrete realization and conditional perturbation comparisons. The missing links to broader rigidity classes, to the intended perturbation costs and to any experiential interpretation remain separate obligations.

\section{Boundary to Null-Regime Instability}

Sections 1--8 establish a controlled assignment model and conditional comparison results. Null-regime conclusions require their own typed witnesses and hypotheses; they do not follow automatically from non-factorization or from a scalar rigidity label.

\subsection{Editorial Boundary}

The instability of the null regime, the no-null theorem, and the attractor-style closure for non-trivial assignments are treated canonically in \textit{Null-Regime Instability}. This paper therefore stops at regime classification, compatibility, fragmentation, forced continuity, and dichotomy, and uses \textit{Null-Regime Instability} as the sole downstream location for the null-instability theorem.

\subsection{Closure of This Paper}

The result of this paper is the classification boundary: if a compatible structural assignment regime exists, its admissible structure is constrained by Sections 1--8. \textit{Null-Regime Instability} addresses the null case with its separately stated witness-relative and conditional hypotheses.

\appendix
\section{Extended Proofs}\label{app:extended-classification-proofs}

\subsection{Proof of Fragmentation Theorem (Extended)}

\begin{proof}[Full Proof of Theorem~\ref{thm:fragmentation}]
Use the specified common space $Z$, map $F$ and finite-cost transport $h_\varepsilon$. Let $x$ be its positive-displacement witness and put $\delta=d_Z(x,h_\varepsilon x)>0$. Apply the lower bound on that same common domain to obtain readout displacement at least $C\delta$. No comparison of set distances is substituted for this pointwise distance. If both readouts are estimated with errors at most $\eta$, the triangle inequality gives estimated separation at least $C\delta-2\eta$; it remains positive when $C\delta>2\eta$. This is a bound on pair separation, not a statement that a particular endpoint lies outside a null ball.
\end{proof}

\subsection{Proof of Forced Continuity Theorem (Extended)}

\begin{proof}[Full Proof of Theorem~\ref{thm:forced-continuity}]
For a state $x$ and error $\epsilon>0$, choose $n$ with $2A_n<\epsilon/2$. Continuity of $g_n$ gives a neighborhood of $x$ where $d_{\mathcal E}(g_n(x),g_n(y))<\epsilon/2$. The two tail errors and the finite-readout difference bound the limiting difference by $\epsilon$. Independently, a zero-displacement comparison satisfies $F(h_\varepsilon x)=F(x)$ exactly. Setwise invariance of the identity object alone would not imply either of these steps.
\end{proof}

\subsection{Structural Necessity Lemma}

\begin{lemma}[Inheritance under Audited Fixed Transport]
An assignment satisfying the zero-displacement comparison branch inherits invariance under that declared intervention class. This applies to CCR realizations only after checking that branch.
\end{lemma}

\begin{proof}
The comparison readout is the restriction of $F$, and every specified transport fixes its argument. Therefore its value is unchanged. This proves the restricted inheritance statement without assuming that scalar rigidity determines arbitrary assignments.
\end{proof}

