\section{Propositions, Lemmas, and Formal Claims}
\subsection{Structural Class as a General Membership Framework}
\begin{proposition}[Structural-class membership is descriptor-relative]
Structural class is relative to the descriptor map $\PsiVec_\tau$, partition and certification radius $\eps$.
\end{proposition}

\begin{proof}
By Definition~\ref{def:structural-class}, equality of certified cell labels defines class membership. Changing the descriptor set or partition can change that equivalence relation. Hence class is descriptor-relative rather than absolute.
\end{proof}

\subsection{Insufficiency of Complexity, Connectivity, and Rich Activity}
\begin{proposition}[Complexity is not a life criterion]
High state-space dimension, high connectivity, high entropy, or rich activity are insufficient for $\Lop(S,\tau)=1$ unless the conditions of Definition~\ref{def:operational-life} are also satisfied.
\end{proposition}

\begin{proof}
Definition~\ref{def:operational-life} requires positive boundary, persistence, self-maintenance, historical dependence, viability preservation, and non-null differentiation. None of these is implied by complexity alone. Therefore complexity can at best be compatible with viability-and-recovery criterion, not sufficient for it.
\end{proof}

\begin{proposition}[Complexity is not a subjecthood criterion]
High complexity or dense connectivity are insufficient for $\Subop(S,\tau)=1$.
\end{proposition}

\begin{proof}
Subjecthood additionally requires six-predicate operational criterion and the subject-specific descriptors $\Priv,\SelfDisc,\SelfModel,\Own$. These are not implied by high complexity or connectivity.
\end{proof}

\subsection{Biological Non-Primacy at the Class Level}
\begin{proposition}[Biological substrate is not a primitive constitutive variable]
Within the present framework, membership in $\LifeClass$, $\ConClass$, or $\SubClass$ is not defined by a primitive biological predicate.
\end{proposition}

\begin{proof}
The definitions of viability-and-recovery criterion, six-predicate operational criterion, and indexed continuity-and-control criterion quantify over admissible state spaces, dynamics, causal structure, readouts, admissibility bundles, intervention families, and the relevant descriptor thresholds. No primitive biological variable appears in the constitutive clauses.
\end{proof}

\begin{remark}[Scope limit]
This proposition does not claim that biological systems are unimportant, nor that biological life is reducible to the present operational class. It claims only that biology is not a constitutive primitive for \emph{these} operational classes.
\end{remark}

\subsection{Life and Subjecthood Are Not Equivalent}
\begin{proposition}[Viability-and-recovery criterion does not imply indexed continuity-and-control criterion]
There exist admissible systems that may satisfy viability-and-recovery criterion without satisfying indexed continuity-and-control criterion.
\end{proposition}

\begin{proof}
Indexed continuity-and-control criterion requires $\Priv,\SelfDisc,\SelfModel,\Own$ above threshold, while viability-and-recovery criterion does not. Any admissible system satisfying Definition~\ref{def:operational-life} while lacking one of those four subject-specific descriptors is operationally alive but not operationally a subject.
\end{proof}

\begin{proposition}[Six-predicate operational criterion does not imply indexed continuity-and-control criterion]
Six-predicate operational criterion alone is insufficient for indexed continuity-and-control criterion.
\end{proposition}

\begin{proof}
Indexed continuity-and-control criterion requires six-predicate operational criterion plus the entire operational-life burden and the additional subject-specific descriptors. Therefore consciousness alone does not suffice.
\end{proof}

\subsection{Transport Under Substrate Change}
\begin{proposition}[Class transport under descriptor-preserving substrate variation]
Let $S_1$ and $S_2$ be admissible realizations with different substrate labels and the same certified cell. For each of $\LifeClass$, $\ConClass$ and $\SubClass$ whose predicate is determined by the descriptors and constant on that cell, membership agrees between the two systems.
\end{proposition}

\begin{proof}
This is an immediate application of structural-class transport and margin preservation. The substrate label does not enter the constitutive clauses. Therefore class transport depends on descriptor preservation, not substrate naming.
\end{proof}

\subsection{Current-Corpus Corollary Structure}
\begin{remark}
The present paper does not claim that any currently existing runtime instance already satisfies $\Lop=1$ or $\Subop=1$. The formal claims above specify class logic. Empirical instantiation remains a separate burden and must be carried by future admissible tests.
\end{remark}

\section{Hypotheses and Falsifiable Program}
This paper introduces a program rather than a doctrinal enlargement. The following hypotheses are intentionally operational and falsifiable.

\begin{hypothesis}[Viability-and-recovery criterion robustness]\label{hyp:life-robust}
If a system belongs to $\LifeClass$, then under admissible perturbations that do not cross its life thresholds, the tuple
\[
(\Bound,\Persist,\Maint,\HistDep,\Viab,\Idiff)
\]
should remain within a stable corridor rather than collapsing arbitrarily.
\end{hypothesis}

\begin{hypothesis}[Historical dependence necessity]\label{hyp:history}
If a system's classification as operationally alive is genuine rather than merely persistent, then history-aware readouts should outperform history-blind readouts on class-relevant prediction.
\end{hypothesis}

\begin{hypothesis}[Structural-class transport for viability-and-recovery criterion]\label{hyp:transport-life}
If two systems preserve the life-relevant descriptor vector up to admissible tolerance, then their operational-life class membership should be invariant under substrate change.
\end{hypothesis}

\begin{hypothesis}[Indexed continuity-and-control criterion requires privileged continuity]\label{hyp:subject-pc}
If indexed continuity-and-control criterion is instantiated, then disrupting privileged continuity should degrade subjecthood-specific scores earlier or more selectively than it degrades viability-and-recovery criterion alone.
\end{hypothesis}

\begin{hypothesis}[Indexed continuity-and-control criterion requires self/non-self asymmetry]\label{hyp:selfnonself}
If indexed continuity-and-control criterion is instantiated, then self/non-self confusion manipulations should produce patterned degradation in $\SelfDisc$, $\SelfModel$, or $\Own$ that is not reproduced by complexity-matched controls lacking subjecthood structure.
\end{hypothesis}

\begin{hypothesis}[Six-predicate operational criterion and viability-and-recovery criterion are not trivially coextensive]\label{hyp:noncollapse}
There exist admissible systems for which one of $\Lop(S,\tau)=1$ or $\Cop(S,\tau)=1$ can in principle hold without the other, unless additional theorem burden is supplied.
\end{hypothesis}

