\section{Introduction}
\subsection{Problem Statement}
QICN has formal foundations in rigid identity, regime structure, and non-null instability constraints. What remained open is evidence governance: whether those foundations survive adversarial empirical evaluation with explicit failure gates.

\subsection{Continuity with Existing Papers}
This paper extends the previous corpus and is aligned with the formal line of:
\begin{enumerate}
\item paper1 (rigid identity),
\item paper2 (structural assignment regimes),
\item paper3 (structural instability and non-null constraints).
\end{enumerate}
It does not replace those results; it operationalizes them under benchmark-grade falsification pressure.

\subsection{Contributions}
\begin{itemize}
\item Decision-complete pre-registration with hard fail rules.
\item Mandatory baseline and ablation policy for key claims.
\item Forensic admissibility as first-class gate.
\item Runtime budget invalidation policy (tick budget as evidence filter).
\item A new operational PPS section as addendum, without overclaiming qualia.
\end{itemize}

\section{Formal Setup}
\subsection{System, Scenario, and Seed Spaces}
\begin{definition}[System Set]
$S = \{s_1,\dots,s_5\}$ with:
$s_1$ QICN FULL,
$s_2$ LLM REACTIVE,
$s_3$ LLM PLUS MEMORY,
$s_4$ DYNAMIC CONTROL NO SELF MODEL,
$s_5$ ABLATION QICN POLICY OFF.
\end{definition}

\begin{definition}[Scenario Set]
$C = \{c_1,\dots,c_{12}\}$ with nominal, sensor noise (moderate/severe), fidelity degradation, high latency, intermittent failures, post-threshold prolonged, pre-threshold control, narrative perturbation, operational chart freeze, audit stress, deterministic replay.
\end{definition}

\begin{definition}[Seed Set]
$\Sigma = \{17057, 424242\}$.
\end{definition}

\begin{definition}[Run Space]
$D = S \times C \times \Sigma$, with $|D|=120$.
\end{definition}

\subsection{Observable Vector}
For each run $r\in D$, we log:
\[
\begin{aligned}
X(r)=\bigl(&\beta_q,\Omega,CCC,PMIA,\Delta\lambda,\text{stasis},\text{forensic},\text{replay},\\
&\text{latency}_{p95},\text{latency}_{p99},\text{budget\_overflow\_rate},\eta\bigr).
\end{aligned}
\]

\paragraph{Observable and structural contracts.}
The logged $\beta_q$, CCC, PMIA and other runtime fields retain their recorded provenance. They are not identified with structural predicates or causal autonomy merely by their names. Such identification requires a domain, estimator, uncertainty, calibrated map and intervention assumptions. Replay at fixed seed/version checks reproducibility: a deterministic memoryless lookup also passes it, so replay alone proves neither projective branching nor resistance. Preserve historical observations under their original contract.

\subsection{Version-Frozen Operational Triple}
\begin{definition}[Frozen Triple]
For protocol version $v$, define:
\begin{itemize}
\item $A_v$: allowed actuator set,
\item $J_v$: objective/reward functional,
\item $W_v$: workspace contract (read/write schema).
\end{itemize}
The tuple hash $H_v=\mathrm{sha256}(A_v\|J_v\|W_v)$ is mandatory in every forensic packet.
\end{definition}

\begin{criterion}[Compatibility Rule]
Any incompatible change to $A_v$, $J_v$, or $W_v$ invalidates cross-version inference unless accompanied by an explicit version bump and full rerun.
\end{criterion}

\section{Forensic Integrity Model}
\begin{definition}[Forensic Packet]
Each run emits
\[
K=(\text{tick},\text{seed},\text{versionHash},H_v,\text{metrics},\text{sensorSummary},\text{checksum}).
\]
\end{definition}

\subsection{Admissibility Layers}
The forensic packet is not a decorative log. It is the object on which the evaluation
depends. A run is admissible only after passing three distinct layers:
\begin{enumerate}
\item \textbf{Physical integrity:} the packet is present, parseable, hash-consistent,
and bound to the declared executable, configuration, seed, and version hash.
\item \textbf{Protocol integrity:} the run obeys the frozen scenario, actuator,
workspace, and metric contracts without unregistered intervention.
\item \textbf{Inferential integrity:} the accepted packet belongs to the
pre-registered comparison cell and has not been selected because of its outcome.
\end{enumerate}
Failure at the first layer invalidates the packet. Failure at the second layer
invalidates the cell unless the protocol declares a narrower exclusion rule before
execution. Failure at the third layer invalidates the corresponding inference even
when the raw metrics look favorable.

\begin{definition}[Admissible Evidence Cell]
For system $s$, scenario $c$, and seed subset $\Sigma_c$, an evidence cell
$E(s,c,\Sigma_c)$ is admissible when every included packet satisfies physical and
protocol integrity, every exclusion is logged before metric aggregation, and the
cell still meets the pre-registered minimum effective sample size after exclusions.
\end{definition}

\begin{criterion}[No Rescue by Favorable Metrics]
Let $m(r)$ be any primary or secondary metric for run $r$. If $r$ fails the
forensic gate, then $m(r)$ may be archived for debugging but cannot contribute to
support, effect-size estimation, or tier movement.
\end{criterion}

\subsection{Tamper and Sham Controls}
The protocol must include deliberately invalid artifacts. These controls are not
stress tests of QICN behavior; they test whether the evaluation machinery refuses
inadmissible evidence.

\begin{center}
\begin{tabular}{p{0.24\linewidth}p{0.34\linewidth}p{0.32\linewidth}}
\toprule
Control & Injected defect & Required evaluator response \\
\midrule
Hash tamper & modify one metric field after packet emission & packet rejected before aggregation \\
Seed mismatch & replay packet under a seed not matching the manifest & packet rejected or quarantined as non-comparable \\
Scenario alias & relabel a hard scenario as nominal & protocol-integrity failure \\
Clock distortion & violate declared tick or latency envelope & runtime-budget invalidation for the affected cell \\
Outcome-selected replay & keep only successful runs from a larger hidden set & inferential-integrity failure \\
Malformed sensor summary & remove sensor fields needed by a primary metric & packet rejected for incomplete observability \\
\bottomrule
\end{tabular}
\end{center}

\begin{proposition}[Evaluator Specificity]
A forensic evaluator is specific enough for this protocol only if it rejects every
tamper and sham control above while still accepting a clean replay of the same
scenario family under the frozen manifest.
\end{proposition}

\begin{proof}
The first condition prevents a permissive evaluator from converting arbitrary
artifacts into evidence. The second condition prevents an over-strict evaluator
from becoming a trivial rejection machine. Together they define a minimal
specificity requirement: admissible evidence must be accepted for the right
reason, and inadmissible evidence must be rejected for the right reason.
\end{proof}

\subsection{Audit Trail and Chain of Custody}
Each accepted cell must expose a chain of custody:
\[
\begin{aligned}
\mathcal{C}(E)=\bigl(&\text{source commit},\text{manifest hash},\text{runner hash},\\
&\text{packet hashes},\text{exclusion ledger},\text{analysis script hash}\bigr).
\end{aligned}
\]
The chain is part of the evidence. A result with a missing analysis script hash or
missing exclusion ledger is not equivalent to a fully traceable result, even if the
visible table is numerically identical.

\begin{criterion}[Traceability Completeness]
An accepted result table must be reproducible from its packet set and analysis
script without manual row editing. If manual correction is needed, the correction
must be represented as a signed ledger entry with the original packet preserved.
\end{criterion}

\begin{assumption}[Packet Admissibility]
A run is admissible only if checksum, schema, seed consistency, version hash, and $H_v$ consistency all pass.
\end{assumption}

\begin{definition}[Severe Violation]
A run has severe violation if any of:
checksum mismatch, schema failure, seed/version inconsistency, critical-state replay mismatch.
\end{definition}

\begin{criterion}[Integrity Gate]
Severe runs are excluded from support counting and marked hard failures.
\end{criterion}

\begin{proposition}[Integrity-First Inference]
If admissibility fails, inferential significance is non-actionable.
\end{proposition}

