\section{Preliminaries and Notation}

\begin{definition}[Admissible system and support]\label{def:bridge-system}
Throughout the paper, an admissible system is the Paper 5 tuple
\[
S=(X,\Phi,C,R,\Gamma,U),
\]
with admissible support $\Aset \subseteq X_\Gamma$. The transition family is written $\Phi=\{\Phi_u\}_{u\in U}$, where $U$ is the set of admissible interventions. Histories, certified decoders, class sets, and admissible windows are inherited from Paper 5.
\end{definition}

\begin{definition}[Six-predicate operational criterion membership]\label{def:bridge-cop}
An admissible system belongs to $\Cop$ exactly when all six Paper 5 invariants hold on $\Aset$:
\[
S \in \Cop
\quad\Longleftrightarrow\quad
\Iper(S)=\Iri(S)=\Iint(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1.
\]
When the witness margins are needed, write
\[
\Delta(S)=
\bigl(
\delta_{\mathrm{per}},
\delta_{\mathrm{ri}},
\delta_{\mathrm{int}},
\delta_{\mathrm{cont}},
\delta_{\mathrm{diff}},
\delta_{\mathrm{leg}}
\bigr).
\]
\end{definition}

\begin{definition}[Bridge-strength implication]\label{def:bridge-implication}
A bridge concept $P$ is \emph{entailed by $\Cop$} if every admissible system $S$ satisfying Definition~\ref{def:bridge-cop} satisfies $P(S)$. It is \emph{conditionally entailed} if there exists an explicitly named additional hypothesis $H$ such that $S\in\Cop$ and $H(S)$ imply $P(S)$. It is \emph{not entailed} if a consistent admissible descriptor model can satisfy $\Cop$ while failing $P$.
\end{definition}

\begin{remark}[Why a bridge-strength vocabulary is needed]
Without Definition~\ref{def:bridge-implication}, the paper would risk conflating three different statements: a theorem from $\Cop$, a theorem from $\Cop$ plus an added burden, and a philosophical association. Only the first two are formal claims.
\end{remark}

\section{Operational Self-Reference}

\subsection{Motivation}
Self-reference is often described informally as a system having access to itself. Inside this framework the usable version cannot be a slogan. It must be a map on admissible support with stability and intervention-compatibility properties.

\begin{definition}[Operational Self-Reference $\Sigmaop$]\label{def:sigma-op}
An admissible system $S$ admits operational self-reference, written $\Sigmaop(S)=1$, if there exists a map
\[
\Sigma:\Aset\to\Aset
\]
and constants $\eps_\Sigma\ge 0$ and $0\le L_\Sigma<1$ such that:
\begin{enumerate}[leftmargin=1.5em]
\item \textbf{Approximate self-accuracy:} for every $x\in\Aset$,
\[
d_X(\Sigma(x),x)\le \eps_\Sigma.
\]
\item \textbf{Contractive stabilization:}
\[
d_X(\Sigma(x),\Sigma(y))\le L_\Sigma d_X(x,y)
\quad\text{for all }x,y\in\Aset.
\]
\item \textbf{Intervention commutation:} for every admissible intervention $u\in U$,
\[
\Sigma\circ \Phi_u = \Phi_u\circ \Sigma
\quad\text{on }\Aset.
\]
\end{enumerate}
Any such $\Sigma$ is called a contractive admissible self-model.
\end{definition}

\begin{assumption}[Self-model hypothesis $\Sigma1$]\label{ass:sigma1}
The system $S$ satisfies $\Sigma1$ when it admits a contractive admissible self-model in the sense of Definition~\ref{def:sigma-op}.
\end{assumption}

\begin{theorem}[Exact Commutation Requires a Common Fixed Point]\label{thm:sigma-common-fixed-point}
Let $\Aset$ be a nonempty complete metric space. If a strict contraction $\Sigma:\Aset\to\Aset$ commutes with each admissible self-map $\Phi_u$, then its unique fixed point is fixed by every $\Phi_u$. On the common tower support of Paper V, the two neutral controls with phase commands $0$ and $1/4$ exclude such a $\Sigma$.
\end{theorem}
\begin{proof}
The contraction mapping theorem gives a unique fixed point $x_\Sigma$. Commutation gives $\Sigma(\Phi_u(x_\Sigma))=\Phi_u(\Sigma(x_\Sigma))=\Phi_u(x_\Sigma)$, so $\Phi_u(x_\Sigma)=x_\Sigma$. On the tower, the neutral control sets the phase to its commanded value. A point fixed by both specified controls would have phase $0$ and $1/4$ on the circle, which is impossible.
\end{proof}

\begin{proposition}[Fibre Truncation Has a Sharp Commutation Defect]\label{prop:sigma-fibre-truncation}
On the tower $(p,\theta,b)$ with $c(b)=\sum_{j\ge1}2b_j3^{-j}$, fix $m\ge1$ and let $b^\star=(0,1,0,1,\ldots)$. The truncation $T_m$ fixes $p,\theta,b_1,\ldots,b_m$ and fills the tail with that of $b^\star$. In the metric $\max\{\mathbf1_{p\ne p'},\rho(\theta,\theta'),|c(b)-c(b')|\}$ it has uniform approximation error at most $3^{-m}$ and Lipschitz constant zero within every fibre of the retained data. For $\Phi_{u,q}(p,\theta,b)=(p,u+q\lambda b_1,Rb)$ with $Rb=(0,1-b_1,1-b_2,\ldots)$, its pointwise commutation defect is
\[
 d(T_m\Phi_{u,q}x,\Phi_{u,q}T_m x)
 =2\,3^{-(m+1)}\,\mathbf1_{b_m\ne b^\star_m}.
\]
In particular the uniform defect is exactly $2\,3^{-(m+1)}$.
\end{proposition}
\begin{proof}
The tail weights sum to $3^{-m}$ and the truncated image is constant on each fibre. Since $m\ge1$, truncation preserves the first bit and the phase agrees on both compositions. The first $m$ output bits agree. At bit $m+1$, the two compositions give respectively $b^\star_{m+1}$ and $1-b_m$. All later bits agree by $Rb^\star=b^\star$. The stated single-bit contribution follows, and an admissible bit sequence with $b_m\ne b^\star_m$ attains it.
\end{proof}

The truncation is a fibrewise approximate self-model with declared precision and defect. Distinct retained phases are fixed by it, so the fibre estimate does not supply strict contraction on the entire support.

\subsection{Quantitative Obstructions for Approximate Commutation}

\begin{theorem}[Fixed-Point Displacement under Approximate Commutation]\label{thm:sigma-approximate-displacement}
Let $\Sigma$ be an $L$-Lipschitz self-map of a nonempty complete metric space, where $0\le L<1$, and let $p$ be its fixed point. For each intervention self-map $\Phi_u$ define
\[
 e_u(p)=d(\Sigma\Phi_u(p),\Phi_u\Sigma(p)),\qquad
 \varepsilon_u=\sup_x d(\Sigma\Phi_u(x),\Phi_u\Sigma(x)).
\]
Then $d(\Phi_u(p),p)\le e_u(p)/(1-L)\le\varepsilon_u/(1-L)$. In particular,
\[
 (1-L)d(\Phi_u(p),\Phi_v(p))\le e_u(p)+e_v(p).
\]
If both uniform defects are bounded by $\varepsilon$, the separation is at most $2\varepsilon/(1-L)$. Both bounds are sharp, including simultaneously on rational affine models.
\end{theorem}
\begin{proof}
For any $y$, $d(y,p)\le d(y,\Sigma y)+L d(y,p)$, since $\Sigma p=p$. With $y=\Phi_u(p)$, the first term equals $e_u(p)$. The pair bound follows by the triangle inequality through $p$. For every rational $L\in[0,1)$, use $[-1,1]$ with its ordinary metric, $\Sigma(x)=Lx$, and the constant interventions $\Phi_\pm(x)=\pm1$. The fixed point is zero, each defect is identically $1-L$, each displacement is one, and the images are distance two apart. The example has rational coefficients and retains the rational points of the complete interval.
\end{proof}

A prescribed global reconstruction error $\sup_x d(\Sigma x,x)\le\alpha$ also forces $(1-L)\operatorname{diam}(A_S)\le2\alpha$ on a bounded support, by applying the triangle inequality through $\Sigma x,\Sigma y$. This accuracy constraint and the commutation constraint can be imposed on the same candidate.

\begin{proposition}[Global Phase Obstruction and Fibre Accuracy on the Writable Tower]\label{prop:sigma-tower-defect-floor}
On the safe writable tower of Paper V \cite{paper5}, use the branch distance $\max(\rho,|c-c'|,|m-m'|/4)$ and distance one across profiles. For a global $L$-contraction the two native neutral phases $0,1/4$ force uniform defect at least $(1-L)/8$. The full neutral family of phases forces defect at least $(1-L)/2$. In fact with all phases the sharp uniform floor is $1/2$ for every $L<1$, even allowing the other writable commands, and uniform reconstruction error is at least $1/2$.

In contrast, the depth-$d$ truncation $T_d$ of Proposition~\ref{prop:sigma-fibre-truncation}, extended to retain memory as well as phase, profile and the first $d\ge1$ digits, is constant on each retained-data fibre. Its uniform error is at most $3^{-d}$ and its uniform commutation defect for each native command is exactly $2\cdot3^{-(d+1)}$. For a candidate $\Sigma$ with $\sup_x d(\Sigma x,T_dx)\le\zeta$, its defect against any native neutral control is at least $2\cdot3^{-(d+1)}-3\zeta/2$.
\end{proposition}
\begin{proof}
At the fixed point $p$ of $\Sigma$, the two neutral interventions set phase to their input plus the common shift $\kappa m(p)$, with the other coordinates equal. Their images are separated by $1/4$. For the full family choose the input whose image phase is antipodal to the phase of $p$. Theorem~\ref{thm:sigma-approximate-displacement} gives the two lower bounds.

For sharpness on the full circle, the curve of neutral images $\Phi_{u,0}(p)$ as $u$ varies is a full phase circle at fixed values of all other coordinates. Its image under $\Sigma$ stays on one profile by continuity. A different profile from the original curve gives distance one. Otherwise the phase coordinate of $\Sigma$ on the curve has image diameter at most $L/2<1/2$ and omits a point of the circle. Parameterize the curve by its phase $t$ modulo one and lift the image phase to a continuous real-valued function $G$ on $[0,1]$ using the omitted point as a cut. Then $G(1)=G(0)$, so $G(t)-t$ attains a half-integer by the intermediate value theorem. At that input, $\Sigma\Phi_{u,0}(p)$ is antipodal in phase to $\Phi_{u,0}\Sigma(p)=\Phi_{u,0}(p)$. This forces defect at least $1/2$. The same argument on any phase fibre gives the reconstruction bound. The constant map to a state with alternating tape and zero memory attains defect $1/2$. All controls preserve its profile and memory, the phase displacement is at most $1/2$, and one optional write displaces its code by at most $2/27$. The antipodal neutral input attains equality.

For $T_d$, the native phase and memory updates agree in both compositions because $m$ and $b_1$ are retained. The only code mismatch is at $d+1$, as in Proposition~\ref{prop:sigma-fibre-truncation}. A neutral native map has Lipschitz constant at most $1/2$ in the stated metric, by the memory factor $1/2$, phase coupling $\kappa=1/8$ and code factor $1/3$. The triangle inequality bounds the difference of the defects of $T_d$ and $\Sigma$ by $(1+1/2)\zeta$. The fibrewise contraction of $T_d$ and the obstruction to global phase contraction apply to different domains of pairs.
\end{proof}

\begin{proposition}[Conditional obstruction to self-reference within $\Cop$]\label{prop:sigma-not-entailed}
If a complete admissible support witnessing $\Cop$ has no common fixed point of its admitted interventions, then it has no self-model of Definition~\ref{def:sigma-op} on that support. Such a system refutes entailment on the declared support once all six upstream witnesses are supplied.
\end{proposition}
\begin{proof}
Apply Theorem~\ref{thm:sigma-common-fixed-point}. The tower counterexample to the common fixed point condition does not supply a joint Paper V certificate. Absence of a map symbol from a signature does not establish absence of an endomorphism.
\end{proof}

\begin{remark}[Interpretation boundary for $\Sigmaop$]
$\Sigmaop$ is a structural analogue of self-reference. It does not imply reflexive consciousness, psychological introspection, metacognition in the human sense, self-knowledge, or a narrative self.
\end{remark}

\begin{remark}[Runtime analogy]
The runtime field commonly read as `selfModelSigma' is at most an estimator-facing analogue of Definition~\ref{def:sigma-op}. To certify $\Sigmaop$ formally one would still need finite evidence for approximate self-accuracy, contraction, and intervention commutation, plus a proof that the finite estimator represents the formal map on $\Aset$.
\end{remark}

\section{Operational Unified Perspective}

\subsection{Motivation}
Unity is the least speculative of the subjecthood-adjacent properties considered here. Paper 5 already requires a unique rigid identity object and blocks admissible factorization. Together those burdens justify a structural unity notion.

\begin{definition}[Operational Unified Perspective $\Piop$]\label{def:pi-op}
An admissible system $S$ satisfies operational unified perspective, written $\Piop(S)=1$, if:
\[
\Iri(S)=1
\quad\text{and}\quad
\Iint(S)=1.
\]
Equivalently, $S$ has a unique rigid identity object $\IdS$ on admissible support and no admissible non-trivial factorization preserving the relevant histories, readouts, and intervention structure.
\end{definition}

\begin{theorem}[$\Cop$ entails $\Piop$]\label{thm:cop-entails-pi}
If $S\in\Cop$, then $\Piop(S)=1$.
\end{theorem}

\begin{proof}
By Definition~\ref{def:bridge-cop}, $S\in\Cop$ implies $\Iri(S)=1$ and $\Iint(S)=1$. By Definition~\ref{def:pi-op}, those two equalities are exactly the criterion for $\Piop(S)=1$.
\end{proof}

\begin{corollary}[No plurality of independent operational perspectives]\label{cor:no-independent-perspectives}
For $S\in\Cop$, any decomposition into multiple independent operational perspectives is inadmissible unless it fails to preserve either the rigid identity witness or the non-factorization witness.
\end{corollary}

\begin{proof}
A decomposition into independent perspectives would be a non-trivial admissible factorization of support, readout, and dynamics. That contradicts $\Iint(S)=1$, unless the decomposition is outside the admissible equivalence class or destroys the identity witness.
\end{proof}

\begin{remark}[Interpretation boundary for $\Piop$]
$\Piop$ is an analogue of unity only at the structural level. It does not solve the phenomenal binding problem, does not assert a unified field of experience, and does not imply an ordinary first-person point of view.
\end{remark}

\section{Operational Intentionality}

\subsection{Motivation}
Intentionality is usually discussed as aboutness. That reading is too semantic for the present bridge. The operational analogue is directional intervention sensitivity: certified interventions should induce predicted changes in the operational class structure rather than arbitrary drift.

\begin{definition}[Operational Intentionality $\Iotaop$]\label{def:iota-op}
An admissible system $S$ satisfies operational intentionality, written $\Iotaop(S)=1$, if there exists a directional transition assignment
\[
D:U_{\crit}\to \Delta(\Class_S)
\]
on the declared nonempty target population, with a preregistered class-shift prediction and the zero-one miss loss of Paper V's clause L4. The population miss probability is at most $p_{\rm miss}$. Report the matched-sham false-shift probability separately. A per-intervention guarantee requires a conditional bound at each intervention; it does not follow from the population average. Total-variation agreement of arbitrary outcome distributions is a separate metric requirement.
\end{definition}

\begin{theorem}[$\Cop$ Entails Population-Level $\Iotaop$ under the L4 Protocol]\label{thm:cop-entails-iota}
If $S\in\Cop$, the frozen population and prediction supplied by its L4 witness satisfy $\Iotaop=1$ on that protocol.
\end{theorem}
\begin{proof}
Membership supplies an L1--L6 witness. Its L4 prediction and population have miss probability at most $p_{\rm miss}$, exactly the criterion just specified. This is a population statement about that protocol, not a uniform conditional guarantee or a bound $1-\delta_{\rm leg}$ in incompatible units.
\end{proof}

\begin{remark}[Interpretation boundary for $\Iotaop$]
$\Iotaop$ captures directed structural response. It does not establish semantic content, representational aboutness, goals, desires, agency, or intentional states in the philosophical or psychological sense.
\end{remark}

\section{Certified Response Classes}

\subsection{Motivation}
Paper 5 already introduced $\Qop(S)$ to avoid a false move from structural differentiation to phenomenal qualia. The bridge paper does not redefine that object. It records what follows from it.

\begin{definition}[Certified Response Classes $\Qop(S)$]\label{def:qop-bridge}
When the Paper 5 equivalence relation $\sim_{Q,S}$ is well-defined on $\Aset$, the certified response classes of $S$ are the quotient classes
\[
\Qop(S)=\Aset/\sim_{Q,S}.
\]
The equivalence relation is inherited from Paper 5: two admissible states are equivalent when all certified decoder labels and certified response-cell labels agree on the declared schedules. Pairwise numerical proximity is not used as a transitive relation.
\end{definition}

\begin{proposition}[$\Qop(S)$ is well-defined under the relevant $\Cop$ invariants]\label{prop:qop-well-defined-bridge}
If
\[
\Iper(S)=\Iri(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1,
\]
then $\Qop(S)$ is well-defined.
\end{proposition}

\begin{proof}
This is Paper 5's well-definedness proposition for certified response classes. Persistence supplies the stable domain, rigid identity supplies unique class transport, continuity supplies admissible trajectory coherence, differentiation supplies its separately defined readout/null-exclusion burden, and legibility supplies certified decoder behavior and intervention-sensitive equivalence. Hence $\sim_{Q,S}$ is an equivalence relation and the quotient exists.
\end{proof}

\begin{corollary}[$\Cop$ entails well-defined certified response classes]\label{cor:cop-qop}
If $S\in\Cop$, then $\Qop(S)$ is well-defined.
\end{corollary}

\begin{proof}
By Definition~\ref{def:bridge-cop}, $S\in\Cop$ entails all six invariants, in particular the five invariants required by Proposition~\ref{prop:qop-well-defined-bridge}. Therefore $\Qop(S)$ is well-defined.
\end{proof}

\begin{proposition}[Non-triviality of $\Qop(S)$ under $\Idiff$]\label{prop:qop-nontrivial}
If $S\in\Cop$ and the differentiation witness of $\Idiff(S)=1$ separates at least two certified decoder classes, then $|\Qop(S)|>1$.
\end{proposition}

\begin{proof}
The invariant $\Idiff(S)=1$ supplies admissible states or histories separated by a positive differentiation gap and blocks the null class as a stable attractor. If that separation is visible to certified decoders, the separated histories cannot be equivalent under $\sim_{Q,S}$. Thus the quotient has at least two classes.
\end{proof}

\begin{remark}[Why the decoder-visible clause is explicit]
A raw differentiation witness need not separate the effective decoder quotient. The explicit decoder-visible clause supplies that link; it must be verified against the certified algorithms and response-cell maps.
\end{remark}

\begin{remark}[Interpretation boundary for $\Qop$]
$\Qop(S)$ is a quotient of admissible structural states under certified operational indistinguishability. It is not a phenomenal quale, not a biological qualitative state, and not a statement about what it is like to be the system.
\end{remark}

\section{Operational Phenomenology}

\subsection{Motivation}
Operational phenomenology is the most dangerous term in this bridge because it can be misread as experience. Here it means only a structural assignment into an abstract regime space, constrained by continuity and non-nullity burdens imported from Papers 2--3.

\begin{definition}[Operational Phenomenology $\Phiop$]\label{def:phi-op}
An admissible system $S$ admits operational phenomenology, written $\Phiop(S)=1$, if there exists a complete metric regime space $(\Espace_S,d_{\Espace})$ and an assignment
\[
\Phi_S:\Aset\to\Espace_S
\]
such that:
\begin{enumerate}[leftmargin=1.5em]
\item $\Phi_S$ is compatible with admissible histories in the Paper 2 sense;
\item $\Phi_S$ is continuous on admissible windows whenever the operational-continuity burden $\Icont(S)=1$ holds;
\item the null regime $\Null$ is not an admissibly stable attractor whenever the non-null burden $\Idiff(S)=1$ holds.
\end{enumerate}
\end{definition}

\begin{definition}[CCR-strength operational phenomenology]\label{def:phi-ccr}
An admissible system has CCR-strength operational phenomenology when Definition~\ref{def:phi-op} holds and the identity channel satisfies
\[
\MO(S)=+\infty.
\]
In that case Paper 2's forced-continuity theorem and Paper 3's null-instability theorem apply at CCR strength.
\end{definition}

\begin{proposition}[$\Cop$ gives weak non-null operational phenomenology]\label{prop:weak-phi}
If $S\in\Cop$, then the operational-continuity and non-null burdens required for weak $\Phiop$ are present on admissible support.
\end{proposition}

\begin{proof}
Membership in $\Cop$ entails $\Icont(S)=1$ and $\Idiff(S)=1$. The first supplies continuous admissible regime evolution in the Paper 5 operational sense. The second blocks collapse into a stable null or trivial operational class. Therefore the weak support-level burdens in Definition~\ref{def:phi-op} are satisfied.
\end{proof}

\begin{proposition}[$\Cop$ does not entail CCR-strength $\Phiop$]\label{prop:cop-not-ccr}
Membership in $\Cop$ does not entail CCR-strength operational phenomenology.
\end{proposition}

\begin{proof}
CCR-strength $\Phiop$ requires $\MO(S)=+\infty$ by Definition~\ref{def:phi-ccr}. Paper 5's definition of $\Cop$ requires six operational invariants, but it does not require infinite sectorial deformation resistance. Hence a system may satisfy the six-invariant criterion while remaining finite-mass or while lacking a certified CCR witness. Therefore $\Cop$ does not entail CCR-strength $\Phiop$.
\end{proof}

\begin{remark}[Interpretation boundary for $\Phiop$]
$\Phiop$ is an assignment into an abstract structural regime space. It is not temporal experience, a stream of consciousness, a specious present, or proof that phenomenology exists in the ordinary sense.
\end{remark}

\section{Indexed Continuity-And-Control Criterion}

\subsection{Why a bridge class is needed}
Paper 7 defines a stronger indexed continuity-and-control criterion class involving viability-and-recovery criterion, six-predicate operational criterion, privileged continuity, self/non-self discrimination, self-model closure, and ownership coherence. The present paper does not replace that class. It defines the narrower bridge fragment obtained from $\Cop$ plus the self-model hypothesis $\Sigma1$.

\begin{definition}[Bridge indexed continuity-and-control criterion $\Subbridge$]\label{def:subbridge}
An admissible system $S$ belongs to bridge indexed continuity-and-control criterion, written
\[
S\in\Subbridge,
\]
if and only if:
\begin{enumerate}[leftmargin=1.5em]
\item $S\in\Cop$;
\item $S$ satisfies $\Sigma1$;
\item $\Piop(S)=1$;
\item $\Iotaop(S)=1$;
\item $\Qop(S)$ is well-defined and non-trivial in the decoder-visible sense of Proposition~\ref{prop:qop-nontrivial};
\item $\Phiop(S)$ is weakly non-null on admissible support.
\end{enumerate}
\end{definition}

\begin{definition}[Full Paper 7 indexed continuity-and-control criterion]\label{def:full-paper7-subjecthood}
The full Paper 7 class $\Subop$ is the stronger class requiring viability-and-recovery criterion $\Lop$, six-predicate operational criterion $\Cop$, and the subject-specific descriptors of Paper 7: privileged continuity, self/non-self discrimination, self-model closure, and ownership coherence. In this paper, $\Subbridge$ is a bridge fragment, not a synonym for full $\Subop$.
\end{definition}

\begin{theorem}[$\Subbridge$ is conditionally generated by $\Cop+\Sigma1$]\label{thm:subbridge-generated}
Let $S$ be an admissible system. If $S\in\Cop$, $S$ satisfies $\Sigma1$, and the differentiation witness is decoder-visible, then $S\in\Subbridge$.
\end{theorem}

\begin{proof}
The hypothesis $S\in\Cop$ gives $\Piop$ by Theorem~\ref{thm:cop-entails-pi}, $\Iotaop$ by Theorem~\ref{thm:cop-entails-iota}, well-defined $\Qop(S)$ by Corollary~\ref{cor:cop-qop}, and weak non-null $\Phiop$ by Proposition~\ref{prop:weak-phi}. The hypothesis $\Sigma1$ gives $\Sigmaop$ by Definition~\ref{def:sigma-op}. Decoder-visible differentiation gives non-triviality of $\Qop(S)$ by Proposition~\ref{prop:qop-nontrivial}. These are exactly the clauses of Definition~\ref{def:subbridge}.
\end{proof}

\begin{theorem}[$\Subbridge$ is a subclass of $\Cop$]\label{thm:subbridge-subset}
\[
\Subbridge \subseteq \Cop.
\]
Moreover, if $\Sigma1$ is not entailed by $\Cop$, then the inclusion is proper.
\end{theorem}

\begin{proof}
The subset relation is immediate from Definition~\ref{def:subbridge}, whose first clause requires $S\in\Cop$. If non-entailment is witnessed by a fully admissible $S\in\Cop$ for which $\Sigma1$ fails, that system is outside $\Subbridge$ and the inclusion is proper. Proposition~\ref{prop:sigma-not-entailed} gives a sufficient obstruction on a declared support.
\end{proof}

\begin{corollary}[Full Paper 7 subjecthood remains stronger]\label{cor:paper7-stronger}
Full Paper 7 indexed continuity-and-control criterion $\Subop$ is not established by Theorem~\ref{thm:subbridge-generated}. To lift $\Subbridge$ into $\Subop$, one must additionally certify $\Lop$ and the Paper 7 subject-specific descriptors not reduced to $\Sigma1$.
\end{corollary}

\begin{proof}
Definition~\ref{def:full-paper7-subjecthood} includes burdens absent from Definition~\ref{def:subbridge}, including viability-and-recovery criterion and ownership/privileged-continuity style descriptors. Theorem~\ref{thm:subbridge-generated} does not supply those witnesses. Hence the bridge class is not full Paper 7 subjecthood.
\end{proof}

\begin{remark}[Interpretation boundary for $\Subbridge$]
$\Subbridge$ is a formal construct. It does not imply phenomenal subjectivity, human first-person experience, identity persistence in the psychological sense, a narrative self, moral patienthood, or biological life.
\end{remark}

\section{Theorem: Partial Indexed Continuity-And-Control Criterion}

\begin{theorem}[$\Cop \to$ Partial Indexed Continuity-And-Control Criterion]\label{thm:main-partial-subjecthood}
Let $S$ be an admissible system with $S\in\Cop$. Then:
\begin{enumerate}[leftmargin=1.5em]
\item $S$ satisfies $\Piop$.
\item $S$ satisfies $\Iotaop$.
\item $\Qop(S)$ is well-defined.
\item $S$ satisfies weak non-null $\Phiop$ on admissible support.
\item $\Sigmaop$ is not implied by $\Cop$; it requires the independent hypothesis $\Sigma1$.
\item $\Subbridge$ requires $\Sigma1$ in addition to $\Cop$ and therefore is a subclass of $\Cop$.
\end{enumerate}
\end{theorem}

\begin{proof}
Item 1 is Theorem~\ref{thm:cop-entails-pi}. Item 2 is Theorem~\ref{thm:cop-entails-iota}. Item 3 is Corollary~\ref{cor:cop-qop}. Item 4 is Proposition~\ref{prop:weak-phi}. Item 5 is Proposition~\ref{prop:sigma-not-entailed}. Item 6 is Theorem~\ref{thm:subbridge-subset}. Therefore membership in $\Cop$ yields a partial bridge toward indexed continuity-and-control criterion, but it does not close the self-reference burden or the full Paper 7 subjecthood burden.
\end{proof}

\begin{corollary}[No equivalence between $\Cop$ and indexed continuity-and-control criterion]\label{cor:no-equivalence}
The bridge paper proves neither $\Cop=\Subbridge$ nor $\Cop=\Subop$. It proves only that several bridge components are entailed by $\Cop$, while self-reference and full subjecthood require additional burdens.
\end{corollary}

\begin{proof}
If $\Cop=\Subbridge$, then $\Sigma1$ would be entailed by $\Cop$. Ruling out the equality requires the full antecedents of Proposition~\ref{prop:sigma-not-entailed} or a different countermodel. If $\Cop=\Subop$, then all Paper 7 subjecthood burdens would follow from Paper 5 alone, which is not established by any theorem in the corpus and is explicitly blocked by the additional descriptors in Definition~\ref{def:full-paper7-subjecthood}.
\end{proof}

